head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf50000";
scwin.gUsrId = undefined;
scwin.dts_usr_basic = null;
scwin.dts_dscl_noti = null;
scwin.dts_pwCheck = null;
scwin.dts_pwHashEnc = null;
scwin.dts_basic = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.dts_usr_basic = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsUsrBasic')) : $c.util.getComponent('dtsUsrBasic');
        scwin.dts_dscl_noti = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsDsclNoti')) : $c.util.getComponent('dtsDsclNoti');
        scwin.dts_pwCheck = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsPwCheck')) : $c.util.getComponent('dtsPwCheck');
        scwin.dts_pwHashEnc = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsPwHashEnc')) : $c.util.getComponent('dtsPwHashEnc');
        scwin.dts_basic = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsBasic')) : $c.util.getComponent('dtsBasic');
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf50000.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.dts_usr_basic.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=USER_INOUT";
        scwin.dts_usr_basic.reset();
        scwin.dts_dscl_noti.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=NOTI_INOUT";
        scwin.dts_dscl_noti.reset();
        scwin.dts_basic.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=USER_INOUT";
        scwin.dts_basic.reset();
        scwin.getSessionData();
        await scwin.readBasicInfo();
        ipt_txb_Pw.hide();
        ipt_txb_EncPw.hide();
        ipt_txb_EncPrePw.hide();
        ipt_txb_EncNewPw.hide();
        $c.util.getComponent('tab_UsrInfo').setSelectedIndex(1);

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf50000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_usr_basic_onloaderror
 * @description dts_usr_basic onloaderror 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.dts_usr_basic_onloaderror = function () {
    try {
        $c.win.alert(scwin.dts_usr_basic);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf50000.dts_usr_basic_onloaderror" });
    }
};

/**
 * @method
 * @name dts_dscl_noti_onloaderror
 * @description dts_dscl_noti onloaderror 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.dts_dscl_noti_onloaderror = function () {
    try {
        $c.win.alert(scwin.dts_dscl_noti);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf50000.dts_dscl_noti_onloaderror" });
    }
};

/**
 * @method
 * @name btn_Modify_1_onclick
 * @description btn_Modify_1 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Modify_1_onclick = async function () {
    try {
        await scwin.sbm_trs_basic_modify();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf50000.btn_Modify_1_onclick' }); }
};

/**
 * @method
 * @name btn_Modify2_onclick
 * @description btn_Modify2 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Modify2_onclick = async function () {
    try {
        const reVal = await scwin.checkCellphoneYn();
        if (reVal === false) {
            return;
        }
        await scwin.modifyDsclNoti();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf50000.btn_Modify2_onclick' }); }
};

/**
 * @method
 * @name trs_pass_check_onfail
 * @description 알림을 띄운다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_pass_check_onfail = async function () {
    try {
        await $c.win.alert('Fail() trs_pass_check' + trs_pass_check.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf50000.trs_pass_check_onfail" });
    }
};

/**
 * @method
 * @name trs_pass_enc_onfail
 * @description 알림을 띄운다
