    }
};

/**
 * @method
 * @name trs_basic_modify_onsuccess
 * @description txb_Msg 을(를) 값을 넣는다 외
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_basic_modify_onsuccess = async function () {
    try {
        $c.util.getComponent("ipt_txb_Msg").setValue($c.data.getMessage("MSG-0001", ""));
        const index = tab_UsrInfo.selectedIndex;
        if (index === 1) {
            await scwin.readBasicInfo();
        } else {
            await scwin.readDsclNoti();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf50000.trs_basic_modify_onsuccess" });
    }
};

/**
 * @method
 * @name trs_basic_modify_onfail
 * @description 알림을 띄운다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_basic_modify_onfail = async function () {
    try {
        await $c.win.alert('Fail()' + trs_basic_modify.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf50000.trs_basic_modify_onfail" });
    }
};

/**
 * @method
 * @name tab_UsrInfo_onselchanged
 * @description tab_UsrInfo onselchanged 이벤트
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tab_UsrInfo_onselchanged = async function (nIndex) {
    try {
        if (nIndex === 1) {
            await scwin.readBasicInfo();
            $c.util.getComponent("ipt_txb_Msg").setValue("");
        } else {
            if (nIndex === 2) {
                await scwin.readDsclNoti();
                $c.util.getComponent("ipt_txb_Msg").setValue("");
            }
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf50000.tab_UsrInfo_onselchanged' }); }
};

/**
 * @method
 * @name dts_dscl_noti_onloadcompleted
