 * @returns {void}
 * @hidden N
 */
scwin.dts_dscl_noti_onloadcompleted = function (rowcount) {

    // alert("DS로딩완료1 :"+dts_dscl_noti.text);
    // alert("DS로딩완료2 :"+dts_dscl_noti.exportdata(1,dts_dscl_noti.getRowCount(),true));

};

/**
 * @method
 * @name btn_Close_1_onclick
 * @description btn_Close_1 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_1_onclick = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    try {
        $c.win.closePopup();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf50000.btn_Close_1_onclick' }); }
};

